static bc_msg_t msg(const unsigned *w)
{
    bc_msg_t m;
    memset(&m, 0, sizeof m);
    m.hdr.count = 29;
    for (int i = 0; i < 29; i++) m.widths[i] = (bc_width_t)w[i];
    return m;
}

int main(void)
{
    unsigned n = sizeof scan / sizeof scan[0], strict = 0, agreed = 0, wrong = 0;
    bool seen_a_run_fail = false;
    for (unsigned i = 0; i < n; i++) {
        bc_msg_t t = msg(scan[i].ms), d = msg(scan[i].ct);
        char expect = scan[i].logged;
        if (expect == '?') {
            expect = 'Z';
            if (!strcmp(scan[i].src, "2a3deb85") && !seen_a_run_fail) { expect = 'A'; seen_a_run_fail = true; }
        }
        char c = route_choose(route_code39_decode(&d), route_code39_decode(&t));
        if (c) strict++;
        else if ((c = route_one_marker_agreed(&t, &d)) != 0) agreed++;
        if (c && c != expect) { wrong++; printf("WRONG %s: %c (expected %c)\n", scan[i].src, c, expect); }
    }
    printf("%u track scans: strict %u, one-marker (agreed) %u more, wrong %u\n", n, strict, agreed, wrong);
    assert(wrong == 0);
    assert(agreed >= 2);
    puts("PASS barcode replay: no wrong letter on any logged track scan");
    return 0;
}
